<script setup lang="ts">
import {confirmAction} from '../ui/confirm'
import {ref,onMounted} from 'vue'
import {request} from '../api'
type Tag={id:string;name:string;records:number;journals:number}
const items=ref<Tag[]>([]),q=ref(''),name=ref(''),editing=ref(''),error=ref(''),busy=ref(false),source=ref<Tag|null>(null),target=ref(''),total=ref(0),page=ref(1),notice=ref('')
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function load(){const d=await request('/admin/tags?'+new URLSearchParams({q:q.value,page:String(page.value)}));items.value=d.items;total.value=d.total;if(target.value&&!items.value.some(t=>t.id===target.value))target.value=''}
async function save(){await run(async()=>{await request('/admin/tags'+(editing.value?'/'+editing.value:''),{method:editing.value?'PUT':'POST',body:JSON.stringify({name:name.value})});name.value='';editing.value='';await load()})}
async function remove(t:Tag){if(!await confirmAction('仅删除未使用标签「'+t.name+'」；历史快照仍保留身份。确认吗？'))return;await run(async()=>{await request('/admin/tags/'+t.id,{method:'DELETE'});await load()})}
async function globalDelete(t:Tag){await run(async()=>{const state=await request('/admin/tags/'+t.id+'/usage');if(!await confirmAction('从库中永久删除「'+t.name+'」，解除 '+state.count+' 篇文章的当前标签关联？文章不删除、历史身份保留且不会自动复活。'))return;await request('/admin/tags/'+t.id+'/delete-everywhere',{method:'POST',body:JSON.stringify({name:t.name,confirmation_token:state.confirmation_token})});notice.value='标签已全局删除，旧编辑页须重新读取';await load()})}
async function merge(){if(!source.value||!target.value)return;const a=source.value,b=items.value.find(x=>x.id===target.value);if(!b){error.value='目标标签已离开当前搜索结果，请重新选择';target.value='';return}if(!await confirmAction(`将「${a.name}」合并到「${b.name}」？来源涉及 ${a.records} 篇动态记录${a.journals?'、'+a.journals+'项历史兼容引用（保留拼写）':''}；重复关联去重，文章不删除。此操作不能直接撤销。`))return;await run(async()=>{await request('/admin/tags/'+a.id+'/merge',{method:'POST',body:JSON.stringify({target_id:b.id,confirm:true})});source.value=null;target.value='';notice.value='合并完成。受影响动态记录已有新修订，旧编辑页须重新读取。';await load()})}
onMounted(()=>run(load))
</script>
<template><section class="admin-content tag-admin"><span class="eyebrow">THE TAG DIRECTORY</span><h1>标签管理</h1><p>跨内容类型整理生活故事；标签改名和合并后保留稳定身份。</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><form class="card" @submit.prevent="save"><h2>{{editing?'修改标签':'创建标签'}}</h2><label>标签名称<input v-model="name" required maxlength="40" /></label><button :disabled="busy">保存标签</button><button v-if="editing" type="button" class="quiet" @click="editing='';name=''">取消</button></form><form class="record-tools" @submit.prevent="page=1;run(load)"><label>按名称搜索<input v-model="q" maxlength="40" /></label><button :disabled="busy">搜索标签目录</button></form><p class="muted">{{total}} 个标签 · 引用数含草稿与回收站，仅管理员可见。合并目标从当前搜索结果选择。</p><article v-for="t in items" :key="t.id" class="card tag-row"><div><h2>{{t.name}}</h2><p>{{t.records}} 篇动态记录<span v-if="t.journals"> · {{t.journals}} 项历史兼容引用</span></p></div><div class="actions"><button class="quiet" :disabled="busy" @click="editing=t.id;name=t.name">重命名</button><button class="quiet" :disabled="busy" @click="source=t;target=''">合并</button><button class="danger" :disabled="busy" @click="globalDelete(t)">全局删除并解除当前关联</button><button class="danger" :disabled="busy||!!t.records||!!t.journals" @click="remove(t)">删除未使用标签</button></div></article><section v-if="source" class="card" aria-label="标签合并确认"><h2>合并标签：{{source.name}}</h2><p>来源涉及 {{source.records}} 篇动态记录<span v-if="source.journals">、{{source.journals}} 项历史兼容引用</span>。不会删除文章或媒体。</p><label>目标标签<select v-model="target" aria-label="目标标签"><option value="">请选择目标</option><option v-for="t in items.filter(x=>x.id!==source?.id)" :key="t.id" :value="t.id">{{t.name}}（{{t.records}} 篇动态记录）</option></select></label><button class="danger" :disabled="busy||!target" @click="merge">确认合并（还需再次确认）</button><button class="quiet" @click="source=null">取消合并</button></section><div class="pagination"><button class="quiet" :disabled="busy||page<=1" @click="page--;run(load)">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(total/50))}}</span><button class="quiet" :disabled="busy||page*50>=total" @click="page++;run(load)">下一页</button></div></section></template>
